// Database access: the shipped, sourced database (db.json, generated by scripts/build-data.ts)
// merged with the user's own entries and calibrations kept in browser storage.

import raw from './db.json';
import type { Bullet, BrassCase, Cartridge, Database, Powder, PowderModelEntry } from './schema';
import type { LoadInputs } from '../engine/adapter';

export const BASE_DB = raw as unknown as Database;

export interface SavedLoad {
  id: string;
  name: string;
  createdIso: string;
  cartridgeId: string | null;
  powderId: string | null;
  bulletId: string | null;
  brassBrandId: string | null;
  inputs: LoadInputs;
  notes?: string;
  measuredVelocityFps?: number | null;
}

export interface UserData {
  version: 1;
  cartridges: Cartridge[];
  powders: Powder[];
  bullets: Bullet[];
  brassCases: BrassCase[];
  /** User calibrations keyed by powder id. They override the shipped model for that powder. */
  powderModels: Record<string, PowderModelEntry>;
  loads: SavedLoad[];
}

export const EMPTY_USER: UserData = { version: 1, cartridges: [], powders: [], bullets: [], brassCases: [], powderModels: {}, loads: [] };

const KEY = 'orka.user.v1';

export function loadUserData(): UserData {
  try {
    const s = globalThis.localStorage?.getItem(KEY);
    if (!s) return { ...EMPTY_USER };
    const parsed = JSON.parse(s);
    return { ...EMPTY_USER, ...parsed, version: 1 };
  } catch {
    return { ...EMPTY_USER };
  }
}

export function saveUserData(u: UserData): boolean {
  try {
    globalThis.localStorage?.setItem(KEY, JSON.stringify(u));
    return true;
  } catch {
    return false;
  }
}

function mergeById<T extends { id: string }>(base: T[], extra: T[]): T[] {
  const map = new Map(base.map((x) => [x.id, x]));
  for (const e of extra) map.set(e.id, { ...e, user: true } as T);
  return [...map.values()];
}

export function mergedDb(user: UserData, base: Database = BASE_DB): Database {
  const powders = mergeById(base.powders, user.powders).map((p) =>
    user.powderModels[p.id] ? { ...p, model: user.powderModels[p.id] } : p,
  );
  return {
    ...base,
    cartridges: mergeById(base.cartridges, user.cartridges),
    powders,
    bullets: mergeById(base.bullets, user.bullets),
    brassCases: [...base.brassCases, ...user.brassCases.map((c) => ({ ...c, user: true }))],
  };
}

/** Validate an imported user-data file. Throws with a readable message on failure. */
export function parseUserImport(text: string): UserData {
  const obj = JSON.parse(text);
  if (typeof obj !== 'object' || obj === null) throw new Error('File is not a JSON object.');
  const out: UserData = { ...EMPTY_USER };
  for (const k of ['cartridges', 'powders', 'bullets', 'brassCases', 'loads'] as const) {
    if (obj[k] !== undefined) {
      if (!Array.isArray(obj[k])) throw new Error(`"${k}" must be an array.`);
      (out as any)[k] = obj[k];
    }
  }
  if (obj.powderModels !== undefined) {
    if (typeof obj.powderModels !== 'object') throw new Error('"powderModels" must be an object.');
    out.powderModels = obj.powderModels;
  }
  return out;
}
